-- Reemplazo completo del catálogo public.productos con el Excel SAG de cítricos y paltos.
-- Conserva la estructura de la tabla, pero no conserva filas ni valores del catálogo anterior.
-- Carga 283 productos normalizados y 812 usos específicos.
-- No crea asociaciones con órdenes, programas, despachos ni movimientos.
-- Si existen referencias operacionales a productos anteriores, aborta sin borrar nada.

begin;

alter table public.productos
  add column if not exists nombre_normalizado text,
  add column if not exists nombre_sag text,
  add column if not exists numero_sag text,
  add column if not exists tipo_producto_sag text,
  add column if not exists color_etiqueta_sag text,
  add column if not exists concentracion_sag text,
  add column if not exists toxicidad_abejas_sag text,
  add column if not exists fuente_sag text,
  add column if not exists actualizado_en timestamptz not null default now();

create table if not exists public.producto_usos_sag (
  id bigint generated always as identity primary key,
  producto_id uuid not null references public.productos(id) on update cascade on delete cascade,
  fila_excel integer not null,
  cultivo text,
  plaga_maleza text,
  objetivo text,
  dosis_texto text,
  dosis_min numeric,
  dosis_max numeric,
  unidad_dosis text,
  base_dosis text not null default 'texto',
  observaciones text,
  tipo_aplicacion text,
  carencia_texto text,
  carencia_dias integer,
  frecuencia text,
  agenda_pesticida text,
  creado_en timestamptz not null default now(),
  actualizado_en timestamptz not null default now(),
  constraint producto_usos_sag_producto_fila_unq unique (producto_id, fila_excel)
);

-- Protección: el reemplazo no elimina información de órdenes ni otras tablas operacionales.
do $$
declare
  referencia record;
  tiene_datos boolean;
begin
  for referencia in
    select ns.nspname as esquema, tabla.relname as tabla, columna.attname as columna
    from pg_constraint fk
    join pg_class tabla on tabla.oid = fk.conrelid
    join pg_namespace ns on ns.oid = tabla.relnamespace
    join pg_attribute columna
      on columna.attrelid = fk.conrelid
     and columna.attnum = fk.conkey[1]
    where fk.contype = 'f'
      and fk.confrelid = 'public.productos'::regclass
      and not (ns.nspname = 'public' and tabla.relname = 'producto_usos_sag')
  loop
    execute format(
      'select exists (select 1 from %I.%I where %I is not null)',
      referencia.esquema, referencia.tabla, referencia.columna
    ) into tiene_datos;

    if tiene_datos then
      raise exception
        'Catálogo no reemplazado: %.% todavía contiene referencias en la columna %. No se borró ningún dato.',
        referencia.esquema, referencia.tabla, referencia.columna;
    end if;
  end loop;
end $$;

delete from public.producto_usos_sag;
delete from public.productos;

