create unique index if not exists productos_nombre_normalizado_uidx
  on public.productos (nombre_normalizado)
  where nombre_normalizado is not null;

create index if not exists producto_usos_sag_producto_idx
  on public.producto_usos_sag (producto_id);
create index if not exists producto_usos_sag_cultivo_idx
  on public.producto_usos_sag (cultivo);

insert into public.producto_usos_sag (
  producto_id, fila_excel, cultivo, plaga_maleza, objetivo, dosis_texto,
  dosis_min, dosis_max, unidad_dosis, base_dosis, observaciones, tipo_aplicacion,
  carencia_texto, carencia_dias, frecuencia, agenda_pesticida
)
select
  p.id, x.fila_excel, x.cultivo, x.plaga_maleza, x.objetivo, x.dosis_texto,
  x.dosis_min, x.dosis_max, x.unidad_dosis, x.base_dosis, x.observaciones,
  x.tipo_aplicacion, x.carencia_texto, x.carencia_dias, x.frecuencia, x.agenda_pesticida
from (values
