  ('AQUICLAN 24 EC', 101, 'Palto, Naranjo, Mandarina, Clementina, Tangelo', 'Hualcacho, Pata de gallina, Ballica, Avenilla, Cebadilla, Pega-pega, Trigo, Cebada, Avena, Maicillo de semilla', 'Hualcacho, Pata de gallina, Ballica, Avenilla, Cebadilla, Pega-pega, Trigo, Cebada, Avena, Maicillo de semilla', '0,4 - 0,6 L/ha', 0.4, 0.6, 'L', 'por_ha', 'Aplicar cuando las malezas tengan 3 a 4 hojas.', 'TERRESTRE', 'Palto: No corresponde; Naranjo: No corresponde; Mandarina: No corresponde; Clementina: No corresponde; Tangelo: No corresponde', 0, null, null),
