  ('AQUILES 24 EC', 110, 'Palto, Naranjo, Mandarina, Clementina, Tangelo', 'Maicillo de rizoma, Chépica (Paspalum sp.)', 'Maicillo de rizoma, Chépica (Paspalum sp.)', '0,6 - 1,0 L/ha', 0.6, 1, 'L', 'por_ha', 'Aplicar cuando las malezas tengan 30 a 40 cm de altura.', 'TERRESTRE', 'Palto: No corresponde; Naranjo: No corresponde; Mandarina: No corresponde; Clementina: No corresponde; Tangelo: No corresponde', 0, null, null),
