  ('CLETODIM 240 EC', 198, 'Palto, Naranjo, Mandarina, Clementina, Tangelo', 'Vulpia', 'Vulpia', '1,5 L/ha', 1.5, 1.5, 'L', 'por_ha', 'Aplicar cuando las malezas estén en sus primeros estados de desarrollo (2 a 3 hojas).', 'TERRESTRE', 'Palto: No corresponde; Naranjo: No corresponde; Mandarina: No corresponde; Clementina: No corresponde; Tangelo: No corresponde', 0, null, null),
  ('CLETODIM 240 EC', 199, 'Palto, Naranjo, Mandarina, Clementina, Tangelo', 'Chépica (Cynodon dactylon)', 'Chépica (Cynodon dactylon)', '1,5 - 2 L/ha', 1.5, 2, 'L', 'por_ha', 'Aplicar sobre estolones de la chépica de hasta 15 cm de largo y 10 cm de altura.', 'TERRESTRE', 'Palto: No corresponde; Naranjo: No corresponde; Mandarina: No corresponde; Clementina: No corresponde; Tangelo: No corresponde', 0, null, null),
  ('CLIP 230 SC', 200, 'Naranjo, Mandarina, Clementina, Tangelo', 'Moho gris (Botrytis cinerea) Moho azul (Penicillium italicum) Moho verde (Penicillium digitatum)', 'Moho gris (Botrytis cinerea) Moho azul (Penicillium italicum) Moho verde (Penicillium digitatum)', '80 - 300 cc/100L de agua', 80, 300, 'cc', 'por_100_l', 'Aplicar en mezcla con agua en ducha o spray, asegurando una adecuada cobertura de la fruta.', 'POSTCOSECHA', null, 0, null, null),
  ('CLIP 230 SC', 201, 'Naranjo, Mandarina, Clementina, Tangelo', 'Moho gris (Botrytis cinerea) Moho azul (Penicillium italicum) Moho verde (Penicillium digitatum)', 'Moho gris (Botrytis cinerea) Moho azul (Penicillium italicum) Moho verde (Penicillium digitatum)', '5 - 20 cc/1 L de cera', 5, 20, 'cc', 'texto', 'Aplicar en mezcla con cera durante el proceso de selección y embalaje, asegurando una adecuada cobertura de la fruta', 'POSTCOSECHA', null, 0, null, null),
  ('CLIP 230 SC', 202, 'Naranjo, Mandarina, Clementina, Tangelo', 'Moho azul (Penicillium italicum) Moho verde (Penicillium digitatum)', 'Moho azul (Penicillium italicum) Moho verde (Penicillium digitatum)', '45 - 220 cc/hl', 45, 220, 'cc', 'por_100_l', 'Aplicar en mezcla con agua caliente por inmersión, asegurando una adecuada cobertura de la fruta.', 'POSTCOSECHA', null, 0, null, null),
  ('CLIP 230 SC', 203, 'Palto', 'Colletotrichum gloeosporoides', 'Colletotrichum gloeosporoides', '200 - 350 cc/100 L de agua', 200, 350, 'cc', 'por_100_l', 'Aplicar diluido en agua, asegurando una buena cobertura de la fruta.', 'POSTCOSECHA', null, 0, null, null),
  ('CLOSER', 204, 'Palto', 'Escama blanca de la hiedra Chanchito blanco de cola larga', 'Escama blanca de la hiedra Chanchito blanco de cola larga', '20 - 40 ml/hL', 20, 40, 'cc', 'por_100_l', 'Iniciar aplicaciones en función del monitoreo. Cuando se requiera un mayor poder de control residual de 35 días (por ejemplo, en temporadas con alta presión de chanchitos blancos), se sugiere utilizar una concentración de 40 ml hL', 'TERRESTRE', 'Palto: 7 días', 7, null, null),
  ('CLOSER', 205, 'Naranjo, Mandarina, Clementina', 'Chanchito blanco, Conchuela negra del olivo, Conchuela acanalada, Mosquita blanca', 'Chanchito blanco, Conchuela negra del olivo, Conchuela acanalada, Mosquita blanca', '20 - 40 mL/hL (Mínimo 400 mL/ha)*', 20, 40, 'cc', 'por_100_l', 'Iniciar aplicaciones previo al cierre de roseta ó en función del monitoreo.', 'TERRESTRE', 'Naranjo: 7 días; Mandarina: 7 días; Clementina: 7 días', 7, null, null),
  ('CLOSER', 206, 'Naranjo, Mandarina, Clementina', 'Áfidos', 'Áfidos', '20 mL/hL', 20, 20, 'cc', 'por_100_l', 'Iniciar aplicaciones previo al cierre de roseta ó en función del monitoreo.', 'TERRESTRE', 'Naranjo: 7 días; Mandarina: 7 días; Clementina: 7 días', 7, null, null),
  ('CLOSER', 207, 'Naranjo, Mandarina, Clementina', 'Escama roja (Aonidiella aurantii)', 'Escama roja (Aonidiella aurantii)', '1000 mL/ha', 1000, 1000, 'cc', 'por_ha', 'Aplicar al inicio de movimiento de ninfas. En casos de alta presión de la plaga, utilizar la dosis más alta del rango recomendado Adaptar volumen de agua para asegurar un excelente cubrimiento del follaje Periodo de protección: 30 días.', 'TERRESTRE', 'Naranjo: 7 días; Mandarina: 7 días; Clementina: 7 días', 7, null, null),
  ('COBRE PREMIUM', 208, 'Naranjo, Mandarina, Clementina', 'Pudrición parda', 'Pudrición parda', '200 - 300 g/100 L', 200, 300, 'g', 'por_100_l', 'Aplicar en otoño, antes o inmediatamente después de las primeras lluvias. Repetir en caso de lluvias frecuentes. Utilizar la dosis mayor en condiciones de media a alta presión de la enfermedad. Utilizar un volumen de agua de hasta 3000 L/ha que permita un adecuado cubrimiento de los árboles.', 'TERRESTRE', 'Naranjo: No corresponde; Mandarina: No corresponde; Clementina: No corresponde', 0, null, null),
