  ('CUPROFORTE', 256, 'Naranjo', ', Pudrición Parda', ', Pudrición Parda', '0,75 - 1,25', 0.75, 1.25, null, 'texto', 'plicaciones otoñales, especialmente después de lluvias.', 'AEREA', null, 0, null, null),
