  ('MAKAZE 75 7 SG', 458, 'Palto, Naranjo, Mandarina, Clementina', 'Correhuela, malva, pila-pila', 'Correhuela, malva, pila-pila', '3,0 - 4,0 kg/ha', 3, 4, 'kg', 'por_ha', 'Pleno crecimiento activo, inicios de floración. Emplear la dosis mayor cuando las malezas a controlar estén más desarrolladas. Frecuencia de aplicación cada 4 meses. Máximo 3 aplicaciones por temporada.', 'TERRESTRE', 'Palto: No corresponde; Naranjo: No corresponde; Mandarina: No corresponde; Clementina: No corresponde', 0, '3 aplicaciones por temporada', null),
  ('MAKAZE 75 7 SG', 459, 'Palto, Naranjo, Mandarina, Clementina', 'MALEZAS ARBUSTIVAS:', 'MALEZAS ARBUSTIVAS:', '1,1 - 1,6 kg/ha', 1.1, 1.6, 'kg', 'por_ha', 'Sobre follaje en activo crecimiento o sobre rebrotes. Emplear la dosis mayor cuando las malezas a controlar estén más desarrolladas. Frecuencia de aplicación cada 4 meses. Máximo 3 aplicaciones por temporada.', 'TERRESTRE', 'Palto: No corresponde; Naranjo: No corresponde; Mandarina: No corresponde; Clementina: No corresponde', 0, '3 aplicaciones por temporada', null),
