  ('POWER MAXX', 596, 'Palto, Naranjo, Mandarina, Clementina, Tangelo', 'Perennes Leñosas (arbustivas)', 'Perennes Leñosas (arbustivas)', '3 - 4 kg/ha', 3, 4, 'kg', 'por_ha', 'Aplicar de 30 a 40 días después de la emergencia.', 'TERRESTRE', 'Palto: No corresponde; Naranjo: No corresponde; Mandarina: No corresponde; Clementina: No corresponde; Tangelo: No corresponde', 0, null, null),
  ('POWER MAXX', 597, 'Palto, Naranjo, Mandarina, Clementina, Tangelo', 'Zarzamora (Rubus spp), Boldo (Peumus boldus), Litre (Lithrea caustica), Maqui (Aristotelia chilensis), Ulex (Ulex europaeus), Bacharis (Baccharis sp.), Roble (Nothofagus obliqua), Quillay (Quillaja saponaria), Fuinque (Lomatia ferruginea), Palqui (Cestrum parqui), Brea o Peril (Plucea absinthiroides)', 'Zarzamora (Rubus spp), Boldo (Peumus boldus), Litre (Lithrea caustica), Maqui (Aristotelia chilensis), Ulex (Ulex europaeus), Bacharis (Baccharis sp.), Roble (Nothofagus obliqua), Quillay (Quillaja saponaria), Fuinque (Lomatia ferruginea), Palqui (Cestrum parqui), Brea o Peril (Plucea absinthiroides)', '3 - 5 kg/ha', 3, 5, 'kg', 'por_ha', 'Aplicar durante la floración de las malezas.', 'TERRESTRE', 'Palto: No corresponde; Naranjo: No corresponde; Mandarina: No corresponde; Clementina: No corresponde; Tangelo: No corresponde', 0, null, null),
  ('POWER MAXX', 598, 'Palto, Naranjo, Mandarina, Clementina, Tangelo', 'Control de tocones', 'Control de tocones', '7 Kg/100L', 7, 7, 'kg', 'por_100_l', 'Inmediatamente después de haber realizado el corte, con la precaución de dejar bien cubierto el cambium.', 'TERRESTRE', 'Palto: No corresponde; Naranjo: No corresponde; Mandarina: No corresponde; Clementina: No corresponde; Tangelo: No corresponde', 0, null, null),
  ('PREDATOR', 599, 'Naranjo, Mandarina, Clementina, Tangelo', 'Chanchito blanco (Pseudococcus viburni, P.calceolariae, P. longispinus, Planococcus citri) y Mosquita blanca (Aleurothrixus floccosus) Escama roja de los cítricos (Aonidiella aurantii)', 'Chanchito blanco (Pseudococcus viburni, P.calceolariae, P. longispinus, Planococcus citri) y Mosquita blanca (Aleurothrixus floccosus) Escama roja de los cítricos (Aonidiella aurantii)', '35 - 45 45', 35, 45, null, 'texto', 'Aplicar según monitoreo de la plaga al detectar los primeros ejemplares con una buena cobertura. Respetar la concentración mínima señalada para los volúmenes de agua indicados en la etiqueta. Emplear la mayor concentración de PREDATOR ante altas infestaciones de la plaga o poblaciones donde se encuentre presente más de una especie de Pseudococcus. Realizar un máximo de 2 aplicaciones por temporada, respetando un mínimo de 14 días antes de una nueva aplicación, hasta 21 días en situaciones normales de infestación. Resguardar los periodos de carencia. Aplicar al follaje, al inicio de movimiento de ninfas, según monitoreo, asegurando un buen cubrimiento. Aplicar como máximo 2 veces en la temporada, con una frecuencia de 14 días.', 'TERRESTRE', 'Naranjo: 14; 21; 7; 25 días; Mandarina: 14; 21; 7; 25 días; Clementina: 14; 21; 7; 25 días; Tangelo: 14; 21; 7; 25 días', 25, '2 aplicaciones por temporada', null),
  ('PREDATOR', 600, 'Naranjo, Mandarina, Clementina, Tangelo', 'Chanchito blanco (Pseudococcus viburni, P.calceolariae, P. longispinus, Planococcus citri) y Mosquita blanca (Aleurothrixus floccosus)', 'Chanchito blanco (Pseudococcus viburni, P.calceolariae, P. longispinus, Planococcus citri) y Mosquita blanca (Aleurothrixus floccosus)', '950 cc/ha', 950, 950, 'cc', 'por_ha', 'Aplicar según monitoreo de las plagas al detectar los primeros ejemplares con una buena cobertura. Realizar un máximo de 2 aplicaciones por temporada respetando un mínimo de 14 días antes de una nueva aplicación, hasta 21 días en situaciones normales de infestación. Resguardar los periodos de carencia.', 'AEREA', 'Naranjo: 14; 21; 7; 25 días; Mandarina: 14; 21; 7; 25 días; Clementina: 14; 21; 7; 25 días; Tangelo: 14; 21; 7; 25 días', 25, '2 aplicaciones por temporada', null),
  ('PROPULSE', 601, 'Clementina', 'Mejorar la producción y aumentar el calibre de los frutos', 'Mejorar la producción y aumentar el calibre de los frutos', '10 - 15 tabletas/100 L de agua', 10, 15, 'L', 'por_100_l', 'Se recomienda la aplicación de 10 tabletas/hL de Propulse a frutitos de 13 a 15 mm de diámetro para años con primaveras cálidas de alta acumulación térmica e incrementar la dosis a 15 tabletas/hL en años de primavera fría, con un mojamiento de 1.500 L de agua por hectárea.', 'TERRESTRE', 'Clementina: 40 días', 40, null, null),
  ('PROPULSE', 602, 'Naranjo', 'Mejorar la producción y aumentar el calibre de los frutos', 'Mejorar la producción y aumentar el calibre de los frutos', '10 - 15 tabletas/100 L de agua', 10, 15, 'L', 'por_100_l', 'Se recomienda la aplicación de 10 tabletas/hL de Propulse a frutitos de 18 a 20 mm de diámetro para años con primaveras cálidas de alta acumulación térmica e incrementar la dosis a 15 tabletas/hL en años de primavera fría, con un mojamiento de 1.500 L/ha.', 'TERRESTRE', 'Naranjo: 40 días', 40, null, null),
  ('PROPULSE', 603, 'Mandarina', 'Mejorar la producción y aumentar el calibre de los frutos', 'Mejorar la producción y aumentar el calibre de los frutos', '10 tabletas/100 L de agua', 10, 10, 'L', 'por_100_l', 'Se recomienda la aplicación de Propulse a frutitos tengan 11 a 12 mm de diámetro. Utilizar un mojamiento de 1.500 L/ha.', 'TERRESTRE', 'Mandarina: 40 días', 40, null, null),
  ('PUELCHE WP', 604, 'Naranjo, Mandarina, Tangelo', 'Pudrición gris o Tizón de la flor (Botrytis cinerea)', 'Pudrición gris o Tizón de la flor (Botrytis cinerea)', '100 - 150 g/hl', 100, 150, 'g', 'por_100_l', 'Se recomienda aplicar en dosis de 100 g/hl con baja presión de la enfermedad y en dosis de 150 g/hl con alta presión. Se recomienda aplicar con condiciones predisponentes para la enfermedad (agua libre o síntomas de la enfermedad). Mojamiento sugerido sobre 1000 l/ha, según estado fenológico, tipo de conducción y/o tamaño de plantas.', 'TERRESTRE', null, 0, null, null),
  ('PUNTO 70 WG', 605, 'Palto, Naranjo, Mandarina, Clementina', 'Pulgón negro de los cítricos (Toxoptera aurantii) Pulgón verde de los cítricos (Aphis citrícola) Pulgón negro de la alfalfa (Aphis craccivora) Pulgón del melón (Aphis gossypii) Pulgón de la espirea (Aphis spiraecola) Mosquita blanca (Aleurothrixus floccosus) Conchuela negra del olivo (Saissetia oleae) Conchuela blanca de la hiedra (Aspidiotus nerii) Conchuela cerosa de los citrus (Ceroplastes cirripediformis) Conchuela hemisférica (Saissetia coffeae) Conchuela acanalada de los cítricos (Icerya purchasi) Escama blanca (Aspidiotus nerii) Hemiberlesia del kiwi (Hemiberlesia rapax) Trips californiano (Frankliniella occidentalis) Chanchito blanco (Pseudococcus viburni)', 'Pulgón negro de los cítricos (Toxoptera aurantii) Pulgón verde de los cítricos (Aphis citrícola) Pulgón negro de la alfalfa (Aphis craccivora) Pulgón del melón (Aphis gossypii) Pulgón de la espirea (Aphis spiraecola) Mosquita blanca (Aleurothrixus floccosus) Conchuela negra del olivo (Saissetia oleae) Conchuela blanca de la hiedra (Aspidiotus nerii) Conchuela cerosa de los citrus (Ceroplastes cirripediformis) Conchuela hemisférica (Saissetia coffeae) Conchuela acanalada de los cítricos (Icerya purchasi) Escama blanca (Aspidiotus nerii) Hemiberlesia del kiwi (Hemiberlesia rapax) Trips californiano (Frankliniella occidentalis) Chanchito blanco (Pseudococcus viburni)', '30 - 40 g/100 L', 30, 40, 'g', 'por_100_l', 'Aplicar al follaje en primavera-verano: Aplicar según monitoreo de la plaga, al observar las primeras ninfas, con un volumen de agua que permita un buen cubrimiento. CubVrimiento sugerido: 2.000 l/ha', 'TERRESTRE', 'Palto: No corresponde; Naranjo: No corresponde; Mandarina: No corresponde; Clementina: No corresponde', 0, null, null),
  ('PURE SPRAY 22 E', 606, 'Naranjo, Mandarina, Clementina', '- Conchuela negra del olivo (Saissetia oleae); conchuela blanda (Coccus hesperidum) y conchuela acanalada (Icerya purchasi). Escama morada de los cítricos (Lepidosaphes beckii); y roja de los cítricos (Aonidiella aurantii). Arañita roja de los cítricos (Panonychus citri)', '- Conchuela negra del olivo (Saissetia oleae); conchuela blanda (Coccus hesperidum) y conchuela acanalada (Icerya purchasi). Escama morada de los cítricos (Lepidosaphes beckii); y roja de los cítricos (Aonidiella aurantii). Arañita roja de los cítricos (Panonychus citri)', '0,7 - 1,0 L/100 L', 0.7, 1, 'L', 'por_100_l', '- Para escamas y conchuelas, aplicar desde migración de ninfas. Frecuencia: repetir la aplicación 15 días después de la primera. Realizar hasta 3 aplicaciones por temporada. Para arañitas aplicar cuando se detecten los primeros ejemplares. Frecuencia: repetir a los 10 días. Realizar hasta 3 aplicaciones por temporada. No aplicar desde floración hasta fruto cuajado de 2 mm. La dosis menor se recomienda cuando la presión de la plaga es baja. La dosis mayor se recomienda para presiones de plaga altas y cuando las condiciones ambientales favorecen su desarrollo. Mojamiento sugerido: 2000 a 4500 L/ha.', 'TERRESTRE', null, 0, 'Repetir cada 10 días; 3 aplicaciones por temporada', null),
  ('PURE SPRAY 22 E', 607, 'Palto', '- Conchuela negra del olivo (Saissetia oleae)', '- Conchuela negra del olivo (Saissetia oleae)', '0,7 - 1,0 L/100 L', 0.7, 1, 'L', 'por_100_l', '- Para control de conchuela negra aplicar cuando las ninfas migratorias hayan salido del interior del caparazón de la hembra en su totalidad y repetir a los 35 - 45 días de acuerdo a monitoreo. Para este tratamiento: 2 aplicaciones. Frecuencia: 35 - 45 días. Mojamiento sugerido: 3000 L/ha.', 'TERRESTRE', null, 0, 'Repetir cada 35 - 45 días', null),
  ('PURE SPRAY 22 E', 608, 'Palto', '- Arañita roja del palto (Oligonychus yothersi)', '- Arañita roja del palto (Oligonychus yothersi)', '0,7 - 1,0 L/100 L', 0.7, 1, 'L', 'por_100_l', '- Aplicar cuando se detecten los primeros ejemplares. Repetir a los 10 - 12 días. Para este tratamiento: 2 aplicaciones. Frecuencia: 10 - 12 días. Mojamiento sugerido: 3000 L/ha.', 'TERRESTRE', null, 0, 'Repetir cada 10 - 12 días', null),
  ('PURE SPRAY GREEN', 609, 'Naranjo, Mandarina, Clementina', 'Conchuela negra del olivo (Saissetia oleae). Conchuela blanda (Coccus hesperidum). Conchuela blanca acanalada (Icerya purchasi). Escama morada (Lepidosaphes becki), blanca (Aspidiotus nerii) y roja (Aonidella auranti). Estados móviles de arañitas (Panonychus citri, Tetranychus urticae, Polifagotarsonemus latus).', 'Conchuela negra del olivo (Saissetia oleae). Conchuela blanda (Coccus hesperidum). Conchuela blanca acanalada (Icerya purchasi). Escama morada (Lepidosaphes becki), blanca (Aspidiotus nerii) y roja (Aonidella auranti). Estados móviles de arañitas (Panonychus citri, Tetranychus urticae, Polifagotarsonemus latus).', '0,7 - 1,0 L/100 L', 0.7, 1, 'L', 'por_100_l', 'Aplicar desde nacimiento de ninfas móviles repitiendo cada 15 días hasta 3 aplicaciones. Para conchuela negra, aplicar entre enero y marzo. Para escama roja y conchuela blanda, entre noviembre y diciembre. Para escama blanca en limoneros, entre abril y mayo. Para arañitas cuando se detecten los primeros ejemplares repitiendo a los 10 días. No en floración. La dosis menor se recomienda cuando la presión de la plaga no es tan importante. La dosis mayor se recomienda para presiones de plaga altas y cuando las condiciones ambientales favorecen su desarrollo. Mojamiento sugerido: 2000 - 4500 L/ha.', 'TERRESTRE', null, 0, 'Cada 15 días', null),
  ('PURE SPRAY GREEN', 610, 'Palto', 'Conchuela negra del olivo (Saissetia oleae). - Escama blanca (Aspidiotus nerii, Hemiberlesia lataniae)', 'Conchuela negra del olivo (Saissetia oleae). - Escama blanca (Aspidiotus nerii, Hemiberlesia lataniae)', '1,0 L/100 L', 1, 1, 'L', 'por_100_l', 'Para control de conchuela negra aplicar con el 80% de las ninfas nacidas y repetir a los 20 días. 2 aplicaciones por temporada. Para escamas blancas aplicar a mediados de verano repitiendo a los 20 días. Mojamiento sugerido: 3000 L/ha.', 'TERRESTRE', null, 0, 'Repetir cada 20 días; 2 aplicaciones por temporada', null),
  ('PURE SPRAY GREEN', 611, 'Palto', 'Arañita estados móviles (Oligonychus yothersi)', 'Arañita estados móviles (Oligonychus yothersi)', '1,0 L/100 L', 1, 1, 'L', 'por_100_l', 'Para estados móviles de arañita, aplicar cuando se detecten los primeros ejemplares. Repetir a los 10 a 12 días. 2 aplicaciones por temporada. Mojamiento sugerido: 3000 L/ha.', 'TERRESTRE', null, 0, 'Repetir cada 10 - 12 días; 2 aplicaciones por temporada', null),
  ('PUZZLE SC', 612, 'Palto, Naranjo, Mandarina, Clementina, Murcott', 'Pulgón negro de los cítricos, verde de los cítricos, negro de la alfalfa, del melón, de la espirea.', 'Pulgón negro de los cítricos, verde de los cítricos, negro de la alfalfa, del melón, de la espirea.', '20 - 30 cc/100 L', 20, 30, 'cc', 'por_100_l', 'Pulgones y Trips: Aplicar al aparecer los primeros ejemplares. Aplicar al inicio del desplazamiento de las ninfas de chanchitos, conchuelas, escamas y mosquitas en primavera -verano. Aplicar una vez en la temporada.', 'TERRESTRE', 'Palto: 30 días; Naranjo: 14 días; Mandarina: 14 días; Clementina: 14 días; Murcott: 14 días', 30, null, null),
  ('PUZZLE SC', 613, 'Palto, Naranjo, Mandarina, Clementina, Murcott', 'Conchuela negra del olivo, blanca de la hiedra, cerosa de los citrus, móvil del olivo, hemisférica, blanda café, acanalada de los cítricos; Escama blanca; Trips californiano; Chanchito blanco de los cítricos, de cola gruesa, de cola larga y de los frutales. Mosquita blanca.', 'Conchuela negra del olivo, blanca de la hiedra, cerosa de los citrus, móvil del olivo, hemisférica, blanda café, acanalada de los cítricos; Escama blanca; Trips californiano; Chanchito blanco de los cítricos, de cola gruesa, de cola larga y de los frutales. Mosquita blanca.', '40 - 60 cc/100 L', 40, 60, 'cc', 'por_100_l', 'Pulgones y Trips: Aplicar al aparecer los primeros ejemplares. Aplicar al inicio del desplazamiento de las ninfas de chanchitos, conchuelas, escamas y mosquitas en primavera -verano. Aplicar una vez en la temporada.', 'TERRESTRE', 'Palto: 30 días; Naranjo: 14 días; Mandarina: 14 días; Clementina: 14 días; Murcott: 14 días', 30, null, null),
  ('PYREMPOST 400 SC', 614, 'Naranjo, Mandarina, Clementina, Clemenules, Murcott', 'Moho Gris, Botritis (Botrytis cinerea) Moho Verde y moho azul (Penicilium spp.)', 'Moho Gris, Botritis (Botrytis cinerea) Moho Verde y moho azul (Penicilium spp.)', '250 cc/100 L', 250, 250, 'cc', 'por_100_l', 'Tratamiento por inmersión por 2 minutos.', 'POSTCOSECHA', 'Naranjo: 0 días; Mandarina: 0 días; Clementina: 0 días; Clemenules: 0 días; Murcott: 0 días', 0, null, null),
  ('PYREMPOST 400 SC', 615, 'Naranjo, Mandarina, Clementina, Clemenules, Murcott', 'Moho Gris, Botritis (Botrytis cinerea) Moho Verde y moho azul (Penicilium spp.)', 'Moho Gris, Botritis (Botrytis cinerea) Moho Verde y moho azul (Penicilium spp.)', '125 cc/100 L', 125, 125, 'cc', 'por_100_l', 'Tratamiento en ducha por 2 a 4 minutos.', 'POSTCOSECHA', 'Naranjo: 0 días; Mandarina: 0 días; Clementina: 0 días; Clemenules: 0 días; Murcott: 0 días', 0, null, null),
  ('PYREMPOST 400 SC', 616, 'Naranjo, Mandarina, Clementina, Clemenules, Murcott', 'Moho Gris, Botritis (Botrytis cinerea) Moho Verde y moho azul (Penicilium spp.)', 'Moho Gris, Botritis (Botrytis cinerea) Moho Verde y moho azul (Penicilium spp.)', '500 cc/100 L', 500, 500, 'cc', 'por_100_l', 'Tratamiento Spray acuoso en línea.', 'POSTCOSECHA', 'Naranjo: 0 días; Mandarina: 0 días; Clementina: 0 días; Clemenules: 0 días; Murcott: 0 días', 0, null, null),
  ('PYREMPOST 400 SC', 617, 'Naranjo, Mandarina, Clementina, Clemenules, Murcott', 'Moho Gris, Botritis (Botrytis cinerea) Moho Verde y moho azul (Penicilium spp.)', 'Moho Gris, Botritis (Botrytis cinerea) Moho Verde y moho azul (Penicilium spp.)', '500 cc/100 L', 500, 500, 'cc', 'por_100_l', 'Tratamiento Spray acuoso en línea de encerado por 1 minuto.', 'POSTCOSECHA', 'Naranjo: 0 días; Mandarina: 0 días; Clementina: 0 días; Clemenules: 0 días; Murcott: 0 días', 0, null, null),
  ('PYREMPOST 400 SC', 618, 'Naranjo, Mandarina, Clementina, Clemenules, Murcott', 'Moho verde (Penicilium digitatum)', 'Moho verde (Penicilium digitatum)', '100 cc/L de agua', 100, 100, 'cc', 'texto', 'Aplicar con sistema cold fogging (niebla fría) tecnología Decco durante 15 minutos, asegurando una cobertura uniforme.', 'POSTCOSECHA', 'Naranjo: 0 días; Mandarina: 0 días; Clementina: 0 días; Clemenules: 0 días; Murcott: 0 días', 0, null, null),
  ('QL AGRI 35', 619, 'Naranjo, Mandarina, Clementina', 'Xiphinema index,Meloidogyne hapla,Meloidogyne incognita, Xiphinema americanum s. I., Criconemella sp., Pratylenchus thornei,P. neglectus, Paratylenchus sp, Helicotylenchus dihystera, Hemicycliophora sp., Tylenchulus semipenetrans', 'Xiphinema index,Meloidogyne hapla,Meloidogyne incognita, Xiphinema americanum s. I., Criconemella sp., Pratylenchus thornei,P. neglectus, Paratylenchus sp, Helicotylenchus dihystera, Hemicycliophora sp., Tylenchulus semipenetrans', '25 - 30 L/ha', 25, 30, 'L', 'por_ha', 'Inyectar QL Agri35 a través del sistema de riego. Las aplicaciones deben realizarse una vez iniciado el crecimiento radicular activo. Aplicar desde brotes de 80 cm hasta antes de cuaja. Si los niveles de poblaciones son muy altos, utilizar la dosis mayor y repetir la aplicación en post- cosecha para mantener baja la población de nemátodos.', 'TERRESTRE', null, 0, null, null),
  ('QL AGRI 35', 620, 'Naranjo, Mandarina, Clementina', 'Xiphinema index,Meloidogyne hapla,Meloidogyne incognita, Xiphinema americanum s. I., Criconemella sp., Pratylenchus thornei,P. neglectus, Paratylenchus sp, Helicotylenchus dihystera, Hemicycliophora sp., Tylenchulus semipenetrans', 'Xiphinema index,Meloidogyne hapla,Meloidogyne incognita, Xiphinema americanum s. I., Criconemella sp., Pratylenchus thornei,P. neglectus, Paratylenchus sp, Helicotylenchus dihystera, Hemicycliophora sp., Tylenchulus semipenetrans', '25 - 30 L/ha', 25, 30, 'L', 'por_ha', 'Inyectar QL Agri35 a través del sistema de riego. Aplicar en primavera una vez iniciado el crecimiento radicular y repetir si es necesario al inicio de un segundo crecimiento de raíces.', 'TERRESTRE', null, 0, null, null),
  ('QUILATE 225 SL', 621, 'Naranjo, Mandarina, Clementina, Tangelo', 'Chancho blanco (Pseudococcus viburni, P. calceolariae, P. longispirus, Planococcus citri) Mosquita blanca (Aleurothrixus floccosus)', 'Chancho blanco (Pseudococcus viburni, P. calceolariae, P. longispirus, Planococcus citri) Mosquita blanca (Aleurothrixus floccosus)', '35 - 45 cc/100 L', 35, 45, 'cc', 'por_100_l', 'Aplicar según muestreo de la plaga. Utilizar un mojamiento de 2.000 - 3.000 L de agua/ha según estado fenológico del cultivo. Hacer máximo de 2 aplicaciones por temporada, con intervalo mínimo de 14 y máximo de 21 días.', 'TERRESTRE', 'Naranjo: 7 días; Mandarina: 7 días; Clementina: 7 días; Tangelo: 7 días', 7, 'Intervalo 21 días; 2 aplicaciones por temporada', null),
  ('QUILATE 225 SL', 622, 'Naranjo, Mandarina, Clementina, Tangelo', 'Chancho blanco (Pseudococcus viburni, P. calceolariae, P. longispirus, Planococcus citri) Mosquita blanca (Aleurothrixus floccosus)', 'Chancho blanco (Pseudococcus viburni, P. calceolariae, P. longispirus, Planococcus citri) Mosquita blanca (Aleurothrixus floccosus)', '950 cc/ha', 950, 950, 'cc', 'por_ha', 'Aplicar según muestreo de la plaga. Utilizar un mojamiento de 60 L de agua/ha según estado fenológico del cultivo. Hacer máximo de 2 aplicaciones por temporada, con intervalo mínimo de 14 con infestaciones altas y máximo de 21 días con infestaciones bajas.', 'AEREA', 'Naranjo: 7 días; Mandarina: 7 días; Clementina: 7 días; Tangelo: 7 días', 7, 'Intervalo 21 días; 2 aplicaciones por temporada', null),
  ('QUILATE 700 WP', 623, 'Naranjo, Mandarina, Clementina, Tangelo', 'Mosquita blanca (Dialeurodes citri), pulgones (Myzus persicae, Aphis citrícola)', 'Mosquita blanca (Dialeurodes citri), pulgones (Myzus persicae, Aphis citrícola)', '15 con un máximo de 300 g/ha', 15, 15, 'g', 'por_ha', 'Aplicar con buen cubrimiento al detectar los primeros ejemplares, de acuerdo con el muestreo. Máximo de 2 aplicaciones por temporada, con intervalo de 21 a 25 días. Mojamiento máximo de 2.000 L/ha.', 'TERRESTRE', 'Naranjo: 10 días; Mandarina: 10 días; Clementina: 10 días; Tangelo: 10 días', 10, 'Intervalo 21 - 25 días; 2 aplicaciones por temporada', null),
  ('QUILATE 700 WP', 624, 'Naranjo, Clementina', 'Chanchitos blancos (Pseudococcus viburni, P. longispinus, P. calceolariae, Planococcus citri)', 'Chanchitos blancos (Pseudococcus viburni, P. longispinus, P. calceolariae, Planococcus citri)', '15 con un máximo de 300 g/ha', 15, 15, 'g', 'por_ha', 'Aplicar con buen cubrimiento al detectar los primeros ejemplares, de acuerdo con el muestreo. Máximo de 2 aplicaciones por temporada, con intervalo de 21 a 25 días. Mojamiento máximo de 2.000 L/ha.', 'TERRESTRE', 'Naranjo: 10 días; Clementina: 10 días', 10, 'Intervalo 21 - 25 días; 2 aplicaciones por temporada', null),
  ('QUILATE 700 WP', 625, 'Naranjo, Mandarina, Clementina, Tangelo', 'Mosquita blanca (Dialeurodes citri), Pulgones (Myzus persicae, Aphis citrícola), chanchos blancos (Pseudococcus viburni, P. longispinus, P. calceolariae, Planococcus citri)', 'Mosquita blanca (Dialeurodes citri), Pulgones (Myzus persicae, Aphis citrícola), chanchos blancos (Pseudococcus viburni, P. longispinus, P. calceolariae, Planococcus citri)', '300 g/ha', 300, 300, 'g', 'por_ha', 'Aplicar al detectar los primeros ejemplares de la plaga. Máximo de 2 aplicaciones por temporada, con intervalos de 21 - 25 días. Mojamiento de 60 L/ha.', 'AEREA', 'Naranjo: 10 días; Mandarina: 10 días; Clementina: 10 días; Tangelo: 10 días', 10, 'Intervalo 21 - 25 días; 2 aplicaciones por temporada', null),
  ('RECOP', 626, 'Naranjo, Mandarina, Clementina', 'Pudrición parda (Phytophthora citrophthora, Phytophthora parasítica)', 'Pudrición parda (Phytophthora citrophthora, Phytophthora parasítica)', '300 - 400 g/100l', 300, 400, 'g', 'por_100_l', 'Aplicar en otoño, antes o inmediatamente después de las primeras lluvias. Repetir la aplicación después de cada lluvia. Mojamiento: 1500 - 2000 L/ha, dependiendo de la especie y edad de los árboles.', 'TERRESTRE', null, 0, null, null),
  ('REDXODUS EX TU F1', 627, 'Palto', 'Arañita roja del palto (Oligonychus yothersi)', 'Arañita roja del palto (Oligonychus yothersi)', '300 - 400 cc/100 L', 300, 400, 'cc', 'por_100_l', 'Realizar dos aplicaciones con un intervalo de 14 días, en presencia de estadios móviles y huevos, con un mojamiento de 1500 L/ha. Aplicar la dosis mayor a mayor incidencia de la plaga.', 'TERRESTRE', null, 0, 'Intervalo 14 días', null),
  ('REDXODUS EX TU F1', 628, 'Naranjo, Mandarina, Clementina, Tangelo', 'Falsa arañita roja de la vid (Brevipalpus chilensis)', 'Falsa arañita roja de la vid (Brevipalpus chilensis)', '200 - 300 cc/100 L', 200, 300, 'cc', 'por_100_l', 'Realizar dos aplicaciones con un intervalo de 14 días, al inicio del establecimiento de la plaga sobre estadios móviles, con un mojamiento de 2000 L/Ha. Aplicar la dosis mayor a mayor incidencia de la plaga.', 'TERRESTRE', null, 0, 'Intervalo 14 días', null),
  ('REGEV', 629, 'Mandarina', 'Oídio (Podosphaera pannosa).', 'Oídio (Podosphaera pannosa).', '0,5 - 0,6 L/há 500 - 600 ml/há', 0.5, 0.6, 'L', 'texto', 'Realizar hasta 3 aplicaciones por temporada desde término de cosecha hasta término de formación de brotes verdes, con intervalos de 7 a 10 días. Utilizar dosis mínima en aplicaciones preventivas, y dosis máxima con presión alta de enfermedad en intervalos de 7 días. Utilizar un volumen de aplicación de 1.500 L de agua/há.', 'TERRESTRE', 'Mandarina: 14 días', 14, 'Intervalo 7 - 10 días; Intervalo 7 días; 3 aplicaciones por temporada', null),
  ('REGLONE', 630, 'Palto, Naranjo, Mandarina, Clementina, Tangelo', 'Pasto quila (Agrostis spp.), Bromo (Bromus spp.), Pasto bermuda (Cynodon dactylon), Hualcacho (Echinochloa crus-galli), Ballica (Lolium spp.), Chépica (Paspalum spp.), Maicillo (Sorghum halepense), Bledo (Amaranthus spp.), Bolsita del pastor (Capsella bursa-pastoris), Correhuela (Convolvulus arvensis), Quingüilla (Chenopodium album), Chamico (Datura stramonium), Galega (Galega officinalis), Malva (Malva parviflora), Manzanilla (Matricaria chamomilla), Sanguinaria (Polygonum aviculare), Verdolaga (Portulaca oleracea), Rábano (Raphanus raphanistrum), Zarzamora (Rubus ulmifolius), Quilloy-quilloy (Stellaria media), Verónica (Veronica persicae) y Chufa (Cyperus esculentus),', 'Pasto quila (Agrostis spp.), Bromo (Bromus spp.), Pasto bermuda (Cynodon dactylon), Hualcacho (Echinochloa crus-galli), Ballica (Lolium spp.), Chépica (Paspalum spp.), Maicillo (Sorghum halepense), Bledo (Amaranthus spp.), Bolsita del pastor (Capsella bursa-pastoris), Correhuela (Convolvulus arvensis), Quingüilla (Chenopodium album), Chamico (Datura stramonium), Galega (Galega officinalis), Malva (Malva parviflora), Manzanilla (Matricaria chamomilla), Sanguinaria (Polygonum aviculare), Verdolaga (Portulaca oleracea), Rábano (Raphanus raphanistrum), Zarzamora (Rubus ulmifolius), Quilloy-quilloy (Stellaria media), Verónica (Veronica persicae) y Chufa (Cyperus esculentus),', '2,0 - 3,0 (1,0 L/100 L de agua)', 2, 3, 'L', 'por_100_l', 'Aplicar sobre las malezas. Normalmente no se requiere reaplicar sobre la misma maleza. Por la emergencia desigual de malezas que ocurre en los campos, puede ser necesario aplicar hasta 5 veces en la temporada (a intervalos de 2-6 semanas) sobre nuevas malezas emergidas. Alternar con productos de diferente modo de acción. Cuidar estrictamente no aplicar REGLONE sobre el cultivo, menos aún sobre corteza inmadura o partes verdes de las especies frutales. En huertos jóvenes aplicar con campana protectora de boquillas, mientras la corteza del árbol esté inmadura. Usar sólo con equipos de aplicación vía terrestre aplicando sobre malezas en activo crecimiento, de preferencia cuando son pequeñas (2 a 4 hojas) y tienen una altura inferior a 10 cm. Es rápidamente absorbido, resistiendo lluvias que puedan caer entre 30 minutos y 1 hora después de la aplicación. Usar las dosis mayores para tratar malezas en infestaciones densas o como primer tratamiento y/o para malezas anuales cercanas a los 10 cm de altura. Es necesario lograr un muy buen mojamiento y cubrimiento de las malezas, utilizando 200 a 300 L de agua/ha. Para el caso de cereales y otros cultivos no frutales utilizar previo a su establecimiento sobre las malezas, nunca aplicar sobre el cultivo.', 'TRATAMIENTO DE SEMILLAS', 'Palto: No corresponde; Naranjo: No corresponde; Mandarina: No corresponde; Clementina: No corresponde; Tangelo: No corresponde', 0, null, null),
  ('RIDOMIL GOLD 480 SL', 631, 'Palto', 'Pudrición del pie o tristeza del palto (Phytophthora cinnamomi)', 'Pudrición del pie o tristeza del palto (Phytophthora cinnamomi)', 'Plantas nuevas y árboles jóvenes de hasta 3 años: 1,0 mL/m2', 3, 3, 'cc', 'texto', 'Aplicar el primer tratamiento al suelo en el momento del transplante. Posteriormente, aplicar hasta 3 veces coincidiendo con los flujos de crecimiento radicular a intervalos de 3 a 6 meses. Aplicar como drench o aspersión a la superficie del suelo, bajo la proyección de la copa del árbol. Se debe asegurar una adecuada distribución del producto en la zona donde se encuentran las raicillas absorbentes. Para obtener mejores resultados se recomienda aplicar en etapas iniciales de la enfermedad o como tratamiento preventivo.', 'TERRESTRE', 'Palto: No corresponde', 0, null, null),
  ('RIDOMIL GOLD 480 SL', 632, 'Palto', 'Pudrición del pie o tristeza del palto (Phytophthora cinnamomi)', 'Pudrición del pie o tristeza del palto (Phytophthora cinnamomi)', 'Arboles en producción: 1,5 - 2,5 mL/m2', 1.5, 2.5, 'cc', 'texto', 'Aplicar al suelo 2 veces por temporada coincidiendo con los flujos de crecimiento radicular de inicio de primavera y fines de verano. Aplicar como drench o aspersión a la superficie del suelo, bajo la proyección de la copa del árbol (5 a 6 meses de intervalo). Luego regar. Repetir las aplicaciones en años alternados. Los árboles maduros, deben tratarse antes o apenas aparezcan los primeros síntomas. Aquellos que están en estados avanzados de la enfermedad pueden no recuperarse. Se debe asegurar una adecuada distribución del producto en la zona donde se encuentran las raicillas absorbentes Para obtener mejores resultados se recomienda aplicar en etapas iniciales de la enfermedad o como tratamiento preventivo. Utilizar la dosis mayor en condiciones favorables para el desarrollo de la enfermedad.', 'TERRESTRE', 'Palto: No corresponde', 0, null, null),
  ('RIDOMIL GOLD 480 SL', 633, 'Naranjo, Mandarina, Clementina, Tangelo', 'Pudrición del pié (Phytophthora citrophthora, Phytophthora parasitica), Pythium spp.', 'Pudrición del pié (Phytophthora citrophthora, Phytophthora parasitica), Pythium spp.', 'Plantas nuevas y árboles jóvenes de hasta 3 años: 1,0 mL/m2', 3, 3, 'cc', 'texto', 'Ala plantación: aplicar en drench a la bolsa antes del transplante Aplicar hasta 2 tratamientos coincidiendo con los flujos de crecimiento radicular a intervalos de 3-6 meses. Aplicar en años alternados. Se debe asegurar una adecuada distribución del producto en la zona donde se encuentran las raicillas absorbentes Para obtener mejores resultados se recomienda aplicar en etapas iniciales de la enfermedad o como tratamiento preventivo.', 'TERRESTRE', 'Naranjo: No corresponde; Mandarina: No corresponde; Clementina: No corresponde; Tangelo: No corresponde', 0, null, null),
  ('RIDOMIL GOLD 480 SL', 634, 'Naranjo, Mandarina, Clementina, Tangelo', 'Pudrición del pié (Phytophthora citrophthora, Phytophthora parasitica), Pythium spp.', 'Pudrición del pié (Phytophthora citrophthora, Phytophthora parasitica), Pythium spp.', 'Arboles en producción: 1,2 - 2,5 mL/m2', 1.2, 2.5, 'cc', 'texto', 'En árboles establecidos hacer dos aplicaciones al suelo a intervalos de 3-6 meses. Aplicar en los períodos de crecimiento radicular para evitar el daño en nuevas raicillas. Repetir las aplicaciones en años alternados. Se debe asegurar una adecuada distribución del producto en la zona donde se encuentran las raicillas absorbentes Para obtener mejores resultados se recomienda aplicar en etapas iniciales de la enfermedad o como tratamiento preventivo. Utilizar la dosis mayor en condiciones favorables para el desarrollo de las enfermedades.', 'TERRESTRE', 'Naranjo: No corresponde; Mandarina: No corresponde; Clementina: No corresponde; Tangelo: No corresponde', 0, null, null),
  ('RIPPER FULL SL', 635, 'Palto, Naranjo, Mandarina, Clementina, Tangelo', 'Malezas anuales de hoja ancha: Alfilerillo, tachuela, relojito (Erodium cicutarium, E. moschatum), Arvejilla, Clarincillo (Vicia benghalensis, V. irsuta, V. sativa), Bledo, Moco de pavo, Penacho (Amaranthus retroflexus), Bolsita del pastor (Capsella bursa-pastoris) Calabacillo (Silene gallica), Cardo de Canadá, Cardo negro (Cirsium arvense, C. vulgare), Chamico (Datura stramonium), Duraznillo (Polygonum persicaria), Falso yuyo (Rapistrum rugosum), Hierba de la culebra (Fumaria capreolata), Manzanilla (Matricaria chamomilla), Malva (Malva nicaensis), Quinguilla (Chenopodium álbum), Quilloy-quilloy (Stellaria media), Pasto pinito (Spergula arvensis), Rábano (Raphanus raphanistrum), Sanguinaria (Polygonium aviculare), Verdolaga (Portulaca oleracea), Verónica (Veronica pérsica), Yuyo (Brassica rapa) Malezas anuales de hoja angosta: Avenilla (Avena fatua), Ballica (Lolium multiflorum), Bromo (Bromus hordeaceus), Hualcacho (Echinochloa crus-galli), Chépica (Paspalum spp.), Pasto quila (Agrostis spp.), Pega - pega (Setaria verticillata), Poa o piojillo (Poa annua), Amor seco (Bidens pilosa)', 'Malezas anuales de hoja ancha: Alfilerillo, tachuela, relojito (Erodium cicutarium, E. moschatum), Arvejilla, Clarincillo (Vicia benghalensis, V. irsuta, V. sativa), Bledo, Moco de pavo, Penacho (Amaranthus retroflexus), Bolsita del pastor (Capsella bursa-pastoris) Calabacillo (Silene gallica), Cardo de Canadá, Cardo negro (Cirsium arvense, C. vulgare), Chamico (Datura stramonium), Duraznillo (Polygonum persicaria), Falso yuyo (Rapistrum rugosum), Hierba de la culebra (Fumaria capreolata), Manzanilla (Matricaria chamomilla), Malva (Malva nicaensis), Quinguilla (Chenopodium álbum), Quilloy-quilloy (Stellaria media), Pasto pinito (Spergula arvensis), Rábano (Raphanus raphanistrum), Sanguinaria (Polygonium aviculare), Verdolaga (Portulaca oleracea), Verónica (Veronica pérsica), Yuyo (Brassica rapa) Malezas anuales de hoja angosta: Avenilla (Avena fatua), Ballica (Lolium multiflorum), Bromo (Bromus hordeaceus), Hualcacho (Echinochloa crus-galli), Chépica (Paspalum spp.), Pasto quila (Agrostis spp.), Pega - pega (Setaria verticillata), Poa o piojillo (Poa annua), Amor seco (Bidens pilosa)', '1,1 - 1,8 L/ha', 1.1, 1.8, 'L', 'por_ha', 'Aplicar dosis de 1,1-1,8 L/ha. con equipos convencionales y con equipos de bajo volumen (CDA) usar 1,1-1,4 L/ha. Para malezas difíciles (Verdolaga y Sanguinaria), usar dosis más alta. Aplicar cuando las malezas tengan 5-15 cm de altura. Repetir la aplicación las veces que sea necesario (máximo 6 aplicaciones por temporada), alternado con productos de diferentes modos de acción. La frecuencia de aplicación está dada por la velocidad de crecimiento de la maleza.', 'TERRESTRE', 'Palto: 3 días; Naranjo: 1 días; Mandarina: 1 días; Clementina: 1 días; Tangelo: 1 días', 3, '6 aplicaciones por temporada', null),
  ('RIPPER FULL SL', 636, 'Palto, Naranjo, Mandarina, Clementina, Tangelo', 'Malezas perennes de hoja ancha: Cerastio (Cerastium arvense, C. fontanum, C. montanum), Correhuela (Convolvulus arvensis), Diente de león, Lechuguilla (Taraxacum officinale), Falso té (Bidens pilosa), Galega (Galega officinalis), Milenrama (Achillea millefolium), Zarzamora (Rubus ulmifolius) Malezas perennes de hoja angosta: Chépica o Pasto quila (Agrostis capillaris), Chépica o Pasto miel (Paspalum dasypleurum, P. cumingii), Maicillo (Sorghum halepense), Pasto cebolla (Arrhenatherum elatius)', 'Malezas perennes de hoja ancha: Cerastio (Cerastium arvense, C. fontanum, C. montanum), Correhuela (Convolvulus arvensis), Diente de león, Lechuguilla (Taraxacum officinale), Falso té (Bidens pilosa), Galega (Galega officinalis), Milenrama (Achillea millefolium), Zarzamora (Rubus ulmifolius) Malezas perennes de hoja angosta: Chépica o Pasto quila (Agrostis capillaris), Chépica o Pasto miel (Paspalum dasypleurum, P. cumingii), Maicillo (Sorghum halepense), Pasto cebolla (Arrhenatherum elatius)', '1,4 - 2,9 L/ha', 1.4, 2.9, 'L', 'por_ha', 'Aplicar 1,4-2,9 L/ha con equipos convencionales y con equipos de bajo volumen (CDA) usar 1,1-2,2 L/ha. Para el control de Falso té y Maicillo, aplicar 30-35 días post emergencia. Para el control de Correhuela aplicar al inicio de la floración. Aplicar las veces que sean necesarias, alternando con productos de diferentes modos de acción.', 'TERRESTRE', 'Palto: 3 días; Naranjo: 1 días; Mandarina: 1 días; Clementina: 1 días; Tangelo: 1 días', 3, null, null),
  ('RIPPER FULL SL', 637, 'Palto, Naranjo, Mandarina, Clementina, Tangelo', 'Pasto bermuda (Cynodon dactylon)', 'Pasto bermuda (Cynodon dactylon)', '2,9 - 4,3 L/ha', 2.9, 4.3, 'L', 'por_ha', 'Aplicar 2,9-4,3 L/ha con equipos convencionales y con equipos de bajo volumen (CDA) usar 2,9-3,6 L/ha. Aplicar con la maleza en activo crecimiento y con estolones de 25 cm. Aplicar las veces que sean necesarias, alternando con productos de diferentes modos de acción.', 'TERRESTRE', 'Palto: 3 días; Naranjo: 1 días; Mandarina: 1 días; Clementina: 1 días; Tangelo: 1 días', 3, null, null),
  ('RIPPER FULL SL', 638, 'Palto, Naranjo, Mandarina, Clementina, Tangelo', 'Chufa (Cyperus esculentus, C. rotundus)', 'Chufa (Cyperus esculentus, C. rotundus)', '2,9 - 4,3 L/ha', 2.9, 4.3, 'L', 'por_ha', 'Aplicar 2,9-4.3 L/ha con equipos convencionales y con equipos de bajo volumen (CDA) usar 2.9-3,6 L/ha. Aplicar cuando la maleza tenga de 10 a 12 hojas. Aplicar las veces que sean necesarias, alternando con productos de diferentes modos de acción.', 'TERRESTRE', 'Palto: 3 días; Naranjo: 1 días; Mandarina: 1 días; Clementina: 1 días; Tangelo: 1 días', 3, null, null),
  ('RIPPER MAX', 639, 'Palto, Naranjo, Mandarina, Clementina, Tangelo', 'Pasto del perro (Bromus sp.). Pega-pega (Setaria sp.), Cola de zorro (Cynosurus echinatus)', 'Pasto del perro (Bromus sp.). Pega-pega (Setaria sp.), Cola de zorro (Cynosurus echinatus)', '1,1 - 1,6 kg/ha', 1.1, 1.6, 'kg', 'por_ha', 'Aplicar con malezas en sus primeros estados 2-4 hojas. Usa dosis mayor en el estado más avanzado.', 'TERRESTRE', 'Palto: No corresponde; Naranjo: No corresponde; Mandarina: No corresponde; Clementina: No corresponde; Tangelo: No corresponde', 0, null, null),
  ('RIPPER MAX', 640, 'Palto, Naranjo, Mandarina, Clementina, Tangelo', 'Hualcacho (Echinochloa sp.)', 'Hualcacho (Echinochloa sp.)', '1,6 kg/ha', 1.6, 1.6, 'kg', 'por_ha', 'Aplicar con malezas en sus primeros estados 2-4 hojas. Usa dosis mayor en el estado más avanzado.', 'TERRESTRE', 'Palto: No corresponde; Naranjo: No corresponde; Mandarina: No corresponde; Clementina: No corresponde; Tangelo: No corresponde', 0, null, null),
  ('RIPPER MAX', 641, 'Palto, Naranjo, Mandarina, Clementina, Tangelo', 'Pata de gallina (Digitaria sanguinalis)', 'Pata de gallina (Digitaria sanguinalis)', '0,8 - 1,3 kg/ha', 0.8, 1.3, 'kg', 'por_ha', 'Aplicar con malezas en sus primeros estados 2-4 hojas. Usa dosis mayor en el estado más avanzado.', 'TERRESTRE', 'Palto: No corresponde; Naranjo: No corresponde; Mandarina: No corresponde; Clementina: No corresponde; Tangelo: No corresponde', 0, null, null),
  ('RIPPER MAX', 642, 'Palto, Naranjo, Mandarina, Clementina, Tangelo', 'Ballicas (Lolium sp.), Avenilla (Avena fatua), Pasto cebolla (Arrhenatherum elatius var bulbosum), Chépica del sur (pasto quila) (Agrostis spp)', 'Ballicas (Lolium sp.), Avenilla (Avena fatua), Pasto cebolla (Arrhenatherum elatius var bulbosum), Chépica del sur (pasto quila) (Agrostis spp)', '1,1 - 1,6 kg/ha', 1.1, 1.6, 'kg', 'por_ha', 'Aplicar con follaje de 10 - 15 cm.', 'TERRESTRE', 'Palto: No corresponde; Naranjo: No corresponde; Mandarina: No corresponde; Clementina: No corresponde; Tangelo: No corresponde', 0, null, null),
