join public.productos p on p.nombre_normalizado = x.nombre_normalizado;

alter table public.producto_usos_sag enable row level security;
drop policy if exists "producto_usos_sag_select_authenticated" on public.producto_usos_sag;
create policy "producto_usos_sag_select_authenticated"
on public.producto_usos_sag for select to authenticated using (true);
grant select on public.producto_usos_sag to authenticated;

commit;

-- Validación esperada: 283 productos y 812 usos SAG.
select
  (select count(*) from public.productos where fuente_sag = 'Excel SAG Cítricos y Paltos') as productos_sag,
  (select count(*) from public.producto_usos_sag) as usos_sag;

